5772: nifs_in_module(Process* p, Eterm module)
5773: {
5774:     Eterm nif_list, *hp;
5775:     Module *mod;
5776: 
5777:     mod = erts_get_module(module, erts_active_code_ix());
5778:     nif_list = NIL;
5779: 
5780:     if (mod->curr.nif != NULL) {
5781:         int func_count, func_ix;
5782:         ErlNifFunc *funcs;
5783: 
5784:         func_count = erts_nif_get_funcs(mod->curr.nif, &funcs);
5785:         hp = HAlloc(p, func_count * 5);
5786: 
5787:         for (func_ix = func_count - 1; func_ix >= 0; func_ix--) {
5788:             Eterm name, arity, pair;
5789:             ErlNifFunc *func;
5790: 
5791:             func = &funcs[func_ix];
5792: 
5793:             name = am_atom_put(func->name, sys_strlen(func->name));
5794:             arity = make_small(func->arity);
5795: 
5796:             pair = TUPLE2(hp, name, arity);
5797:             hp += 3;
5798: 
5799:             nif_list = CONS(hp, pair, nif_list);
5800:             hp += 2;
5801:         }
5802:     }
5803: 
5804:     return nif_list;
5805: }
